from pathlib import Path
import sys,json,hashlib,xml.etree.ElementTree as E,argparse
ap=argparse.ArgumentParser();ap.add_argument('--workspace-root',type=Path,required=True);R=ap.parse_args().workspace_root.resolve();D=Path(__file__).parent
sys.path.insert(0,str(R/'anal'));from stp_resources import Archive
sha=lambda b:hashlib.sha256(b).hexdigest();original=Archive(R.parent/'origin/Table.stp');working=Archive(R/'Table.stp')
member='Table/QuestInfo.xml';raw=original.read(member);assert raw==working.read(member);assert sha(raw)=='5d251415fdfdc453adefbff03114ded5a8ea41b696ce0aab86a23070e0fdca60';quests={int(q.get('id')):q for q in E.fromstring(raw)}
contentPath=R/'runtime-observations/20261107-alsmeer-mainline/story-content-v34.json';content=json.loads(contentPath.read_text(encoding='utf-8'));rows=[]
for i,q in enumerate(content['quests']):
 source=quests[q['quest']];assert int(source.get('level'))==q['levelRaw'];assert int(source.get('town'))==q.get('town',1)
 etc=source.find('RewardsEtc');items=source.find('RewardsItem');rewards=[]
 for n in [] if etc is None else list(etc):
  typ=int(n.get('type'));amount=int(n.get('value'));rewards.append({'rawType':typ,'rawValue':amount,'clientDisplayBinding':{2:'PartyExp',4:'Leeloo'}.get(typ,'UNRESOLVED'),'serverGrantBinding':'UNRESOLVED_NOT_PAID'})
 rows.append({'questIndex':i,'quest':q['quest'],'town':int(source.get('town')),'requiredLevelRaw':int(source.get('level')),'demands':[int(n.get('id')) for n in source.findall('Demands/Demand')],'giver':int(source.get('giver')),'finisher':int(source.get('finisher')),'rewardsEtcPresent':etc is not None,'rewardsEtc':rewards,'rewardsItemPresent':items is not None,'rewardsItemRows':[] if items is None else [dict(n.attrib) for n in items],'rewardAuthority':'RAW_CLIENT_RESOURCE_NOT_SETTLEMENT_POLICY','requiresLevelBeyondPublishedPrototype5':int(source.get('level'))>5})
upgrade='Table/CharUpgradeInfo.xml';uraw=original.read(upgrade);assert uraw==working.read(upgrade);u=E.fromstring(uraw)
assert u.tag=='CHAR_UPGRADE_INFO' and not list(u)
result={'schema':'S00_NORMAL_MAINLINE_PROGRESSION_AUDIT_V1','sourceQuestMember':{'member':member,'sha256':sha(raw),'originalWorkingEqual':True},'storyContentSha256':sha(contentPath.read_bytes()),'questCount':len(rows),'rows':rows,'prototypePublication':{'maximumFixedActiveRoleLevel':5,'Isilia':2,'Pipa':1,'otherKnownStarterRoles':5,'debugLevelFloorExcluded':True,'qualification':'STATIC_SERVER_CODE_UPPER_BOUND_NOT_LIVE_CLIENT_RECORD_INSPECTION'},'firstRequirementBeyondPrototype5':next(r['quest'] for r in rows if r['requiresLevelBeyondPublishedPrototype5']),'numberRequiringBeyond5':sum(r['requiresLevelBeyondPublishedPrototype5'] for r in rows),'unfilledCurveCandidate':{'member':upgrade,'sha256':sha(uraw),'rootTag':u.tag,'childCount':len(list(u)),'qualification':'THIS_EXACT_MEMBER_ONLY_NOT_GLOBAL_ABSENCE_OF_EXP_CURVE'},'unresolved':['Legal quest acceptance/objectives/turn-in settlement versus narrative completion.','PartyExp allocation and units, role/party recipients, real progression policy.','Native EXP update/presentation fields and any real levelcurve.','005C rawDWORDs4/8/C are not EXP just because previouslyunknown.','MissingRewardsEtc does not mean zero approvedreward.'],'clientTargetSha256':'9741d1975327b9309d82b52f631165bc410757694d7c183a5eed970a53ebef91','noRuntimeOrClientMutation':True}
(D/'audit.json').write_bytes((json.dumps(result,ensure_ascii=False,indent=2)+'\n').encode());print(json.dumps({'quests':len(rows),'firstBeyond5':result['firstRequirementBeyondPrototype5'],'needsBeyond5':result['numberRequiringBeyond5'],'rewardRows':sum(len(r['rewardsEtc']) for r in rows)}))
